<script setup>
import { Head, useForm } from '@inertiajs/vue3';
import AdminLayout from '../../../Layouts/AdminLayout.vue';
import AdminPageHeader from '../../../Components/Admin/AdminPageHeader.vue';
import AdminCard from '../../../Components/Admin/AdminCard.vue';
import AdminButton from '../../../Components/Admin/AdminButton.vue';
import StatusBadge from '../../../Components/Admin/StatusBadge.vue';

const props = defineProps({ lead: Object, statusOptions: Array, statusUrl: String, noteUrl: String });
const statusForm = useForm({ status: props.lead.status });
const noteForm = useForm({ note: '' });
const updateStatus = () => statusForm.patch(props.statusUrl, { preserveScroll: true });
const addNote = () => noteForm.post(props.noteUrl, { preserveScroll: true, onSuccess: () => noteForm.reset() });
const copy = async value => { if (value) await navigator.clipboard.writeText(value); };
const date = value => value ? new Intl.DateTimeFormat('id-ID', { dateStyle: 'medium', timeStyle: 'short' }).format(new Date(value)) : '—';
const fields = [ ['Perusahaan', 'company'], ['Email', 'email'], ['WhatsApp', 'whatsapp'], ['Jenis project', 'project_type'], ['Estimasi budget', 'budget_range'], ['Target waktu', 'target_timeline'], ['Sumber', 'source'] ];
</script>
<template>
    <Head :title="`${lead.name} | Lead Admin`"><meta name="robots" content="noindex, nofollow"/></Head>
    <AdminLayout><AdminPageHeader :title="lead.name" description="Detail inquiry asli dan tindak lanjut internal."><template #action><AdminButton href="/admin/leads" variant="secondary">Kembali ke Leads</AdminButton></template></AdminPageHeader><div class="grid gap-5 xl:grid-cols-[minmax(0,1fr)_23rem]"><div class="space-y-5"><AdminCard class="p-5 sm:p-6"><div class="flex flex-col gap-4 border-b border-sch-border pb-5 sm:flex-row sm:items-center sm:justify-between"><div><h2 class="font-bold text-sch-navy">Informasi kontak & project</h2><p class="mt-1 text-xs text-sch-muted">Diterima {{ date(lead.created_at) }}</p></div><StatusBadge :value="lead.status"/></div><dl class="mt-5 grid gap-5 sm:grid-cols-2"><div v-for="([label, key]) in fields" :key="key"><dt class="text-xs font-semibold uppercase tracking-wide text-sch-muted">{{ label }}</dt><dd class="mt-1 break-words text-sm font-medium text-sch-ink">{{ lead[key] || '—' }}</dd><button v-if="key === 'email' || key === 'whatsapp'" type="button" class="mt-2 min-h-10 rounded-lg text-xs font-semibold text-sch-blue hover:underline" @click="copy(lead[key])">Salin {{ label }}</button></div></dl></AdminCard><AdminCard class="p-5 sm:p-6"><h2 class="font-bold text-sch-navy">Pesan / kebutuhan</h2><p class="mt-4 whitespace-pre-wrap text-sm leading-7 text-slate-700">{{ lead.message }}</p></AdminCard><AdminCard class="p-5 sm:p-6"><h2 class="font-bold text-sch-navy">Catatan internal</h2><form class="mt-4" @submit.prevent="addNote"><label for="lead-note" class="sr-only">Catatan internal baru</label><textarea id="lead-note" v-model="noteForm.note" rows="4" class="w-full rounded-xl border border-sch-border px-3.5 py-3 text-sm" placeholder="Tambahkan konteks tindak lanjut..." :aria-invalid="noteForm.errors.note ? 'true' : undefined"/><p v-if="noteForm.errors.note" class="mt-1.5 text-sm text-red-700">{{ noteForm.errors.note }}</p><div class="mt-3 flex justify-end"><AdminButton type="submit" :disabled="noteForm.processing">Tambah Catatan</AdminButton></div></form><div v-if="lead.notes?.length" class="mt-6 space-y-3"><article v-for="note in lead.notes" :key="note.id" class="rounded-xl border border-sch-border bg-slate-50 p-4"><p class="whitespace-pre-wrap text-sm leading-6 text-sch-ink">{{ note.note }}</p><p class="mt-3 text-xs text-sch-muted">{{ note.user?.name || 'Administrator' }} · {{ date(note.created_at) }}</p></article></div><p v-else class="mt-5 rounded-xl bg-slate-50 p-4 text-sm text-sch-muted">Belum ada catatan internal.</p></AdminCard></div><aside class="space-y-5"><AdminCard class="p-5"><h2 class="font-bold text-sch-navy">Perbarui status</h2><form class="mt-4 space-y-3" @submit.prevent="updateStatus"><label for="lead-status" class="text-sm font-semibold text-sch-navy">Status lead</label><select id="lead-status" v-model="statusForm.status" class="min-h-11 w-full rounded-xl border border-sch-border px-3 text-sm"><option v-for="option in statusOptions" :key="option.value" :value="option.value">{{ option.label }}</option></select><AdminButton type="submit" class="w-full" :disabled="statusForm.processing">Simpan Status</AdminButton></form></AdminCard><AdminCard class="p-5"><h2 class="font-bold text-sch-navy">Status email</h2><dl class="mt-4 space-y-3 text-sm"><div><dt class="text-sch-muted">Terkirim</dt><dd class="mt-1 font-medium text-sch-ink">{{ date(lead.email_sent_at) }}</dd></div><div><dt class="text-sch-muted">Gagal</dt><dd class="mt-1 font-medium text-sch-ink">{{ date(lead.email_send_failed_at) }}</dd></div></dl></AdminCard></aside></div></AdminLayout>
</template>
